<style>
.bz501-page .tc-contact-page{--tc-accent:#c52a13;background:linear-gradient(135deg,#f4f5f6,#fafafa);color:#30383b;padding-bottom:72px;font-family:"Be Vietnam Pro",Arial,sans-serif}
.bz501-page .tc-contact-container{width:var(--bz-container);max-width:none;margin-inline:auto}
.bz501-page .tc-contact-breadcrumb{padding:24px 0 8px;color:#727b80}
.bz501-page .tc-contact-breadcrumb a{color:inherit}
.bz501-page .tc-contact-heading{max-width:none;padding:28px 0 36px}
.bz501-page .tc-contact-heading>span{color:#c52a13;font-size:12px;font-weight:700;letter-spacing:.12em;text-transform:uppercase}
.bz501-page .tc-contact-heading h1{font:700 clamp(32px,3.5vw,46px)/1.15 "Be Vietnam Pro",Arial,sans-serif;color:#30383b;margin:12px 0 18px;letter-spacing:-.025em}
.bz501-page .tc-contact-heading p{max-width:740px;color:#626d73;font-size:16px;line-height:1.8}
.bz501-page .tc-contact-copy{padding:24px 28px;background:#fff;border:1px solid #e3e7ea;border-radius:12px;color:#626d73;margin-bottom:30px}
.bz501-page .tc-contact-copy>:first-child{margin-top:0}.bz501-page .tc-contact-copy>:last-child{margin-bottom:0}
.bz501-page .tc-contact-layout{grid-template-columns:minmax(0,.85fr) minmax(0,1.35fr);gap:28px}
.bz501-page .tc-contact-info{padding:36px;background:linear-gradient(135deg,#30383b,#1e2529);color:#fff;border:1px solid #30383b;border-radius:14px;box-shadow:0 16px 40px #30383b0d}
.bz501-page .tc-contact-layout h2{font:700 25px/1.3 "Be Vietnam Pro",Arial,sans-serif;margin:0 0 12px}
.bz501-page .tc-contact-info>p{color:#c6cdd1;font-size:14px;line-height:1.8}
.bz501-page .tc-contact-item{padding:24px 0;border-top:1px solid #ffffff24;gap:18px}
.bz501-page .tc-contact-item>.tc-contact-icon{width:44px;height:44px;flex-basis:44px;border-radius:10px;background:#ffffff0d;color:#ff8a75}
.bz501-page .tc-contact-item h3{color:#c6cdd1;font-size:12px;margin-bottom:8px}
.bz501-page .tc-contact-item p,.bz501-page .tc-contact-item a{color:#fff;font-size:15px;line-height:1.75}
.bz501-page .tc-contact-item a:hover,.bz501-page .tc-contact-item .tc-contact-directions{color:#ffac9b}
.bz501-page .tc-contact-form-card{padding:36px;background:#fff;border:1px solid #e3e7ea;border-radius:14px;box-shadow:0 16px 40px #30383b08}
.bz501-page .tc-contact-form-card>p{color:#727b80;font-size:14px}
.bz501-page .tc-contact-fields{gap:20px 18px}
.bz501-page .tc-contact-fields label{font-size:13px;color:#30383b}
.bz501-page .tc-contact-fields input,.bz501-page .tc-contact-fields textarea{border:1px solid #dce1e5;border-radius:8px;background:#fafafa;color:#30383b;padding:13px 14px;font:14px/1.6 "Be Vietnam Pro",Arial,sans-serif}
.bz501-page .tc-contact-fields textarea{min-height:160px}
.bz501-page .tc-contact-fields input:focus,.bz501-page .tc-contact-fields textarea:focus{outline:2px solid #ff8a7560;outline-offset:1px;border-color:#c52a13;background:#fff}
.bz501-page .tc-contact-fields [aria-invalid=true]{border-color:#c43939}
.bz501-page .tc-contact-fields small{color:#727b80}
.bz501-page .tc-contact-form-card button{min-height:48px;border-radius:8px;background:#c52a13;color:#fff;font:700 14px "Be Vietnam Pro",Arial,sans-serif;padding:14px 26px;margin-top:24px}
.bz501-page .tc-contact-form-card button:hover{background:#a82410}
.bz501-page .tc-contact-page a:focus-visible,.bz501-page .tc-contact-page button:focus-visible{outline:3px solid #ff8a75;outline-offset:3px}
@media(max-width:800px){.bz501-page .tc-contact-layout{grid-template-columns:1fr;gap:24px}.bz501-page .tc-contact-info,.bz501-page .tc-contact-form-card{padding:28px}}
@media(max-width:480px){.bz501-page .tc-contact-page{padding-bottom:40px}.bz501-page .tc-contact-heading{padding:22px 0 28px}.bz501-page .tc-contact-heading h1{font-size:32px}.bz501-page .tc-contact-info,.bz501-page .tc-contact-form-card{padding:24px}.bz501-page .tc-contact-fields{grid-template-columns:1fr;gap:18px}.bz501-page .tc-contact-form-card button{width:100%}}
</style>
